[CmdletBinding()]
param(
  [string]$RuntimePackageKey = "win-x64-trt11.0-cuda13.2-cudnn9.22",
  [string]$LinuxRuntimePackageKey = "linux-x64-ubuntu22.04-trt11.0-cuda13.2-cudnn9.22",
  [string]$RepositoryRoot
)

$ErrorActionPreference = "Stop"

if ([string]::IsNullOrWhiteSpace($RepositoryRoot)) {
  if ([string]::IsNullOrWhiteSpace($PSScriptRoot)) {
    $scriptRoot = (Get-Location).Path
  }
  else {
    $scriptRoot = $PSScriptRoot
  }

  $RepositoryRoot = (Resolve-Path (Join-Path $scriptRoot "..")).Path
}

$utf8 = [System.Text.UTF8Encoding]::new($false)
[Console]::OutputEncoding = $utf8
$OutputEncoding = $utf8

function Write-Utf8FileWithRetry {
  param(
    [string]$LiteralPath,
    [AllowNull()][object]$InputObject,
    [int]$MaxAttempts = 8,
    [int]$DelayMilliseconds = 250
  )

  $directory = Split-Path -Parent $LiteralPath
  if (-not [string]::IsNullOrWhiteSpace($directory)) {
    New-Item -ItemType Directory -Path $directory -Force | Out-Null
  }

  $content = @($InputObject) -join [Environment]::NewLine
  $tempPath = Join-Path $directory (".{0}.{1}.tmp" -f ([IO.Path]::GetFileName($LiteralPath)), [Guid]::NewGuid().ToString("N"))
  [IO.File]::WriteAllText($tempPath, $content + [Environment]::NewLine, $script:utf8)

  for ($attempt = 1; $attempt -le $MaxAttempts; $attempt++) {
    try {
      Move-Item -LiteralPath $tempPath -Destination $LiteralPath -Force
      return
    }
    catch [System.IO.IOException] {
      if ($attempt -eq $MaxAttempts) {
        throw
      }

      Start-Sleep -Milliseconds $DelayMilliseconds
    }
    catch [System.UnauthorizedAccessException] {
      if ($attempt -eq $MaxAttempts) {
        throw
      }

      Start-Sleep -Milliseconds $DelayMilliseconds
    }
  }
}

function Read-JsonOrNull {
  param([string]$RelativePath)

  $path = Join-Path $RepositoryRoot $RelativePath
  if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
    return $null
  }

  return Get-Content -LiteralPath $path -Raw -Encoding utf8 | ConvertFrom-Json
}

function Get-PropertyOrDefault {
  param(
    [AllowNull()][object]$Object,
    [string]$Name,
    [AllowNull()][object]$DefaultValue
  )

  if ($null -eq $Object) {
    return $DefaultValue
  }

  if ($Object.PSObject.Properties.Name -contains $Name) {
    return $Object.$Name
  }

  return $DefaultValue
}

function Normalize-PostPublishRequiredEvidence {
  param([AllowNull()][object]$Evidence)

  $items = @($Evidence | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { [string]$_ })
  foreach ($requiredField in @("noLocalPackageSource", "noLocalNupkgPackageReference")) {
    if ($items -notcontains $requiredField) {
      $items += $requiredField
    }
  }

  return @($items)
}

function Get-ArrayPropertyCountOrDefault {
  param(
    [AllowNull()][object]$Object,
    [string]$Name,
    [int]$DefaultValue
  )

  if ($null -eq $Object) {
    return $DefaultValue
  }

  if (-not ($Object.PSObject.Properties.Name -contains $Name)) {
    return $DefaultValue
  }

  $value = $Object.$Name
  if ($null -eq $value) {
    return $DefaultValue
  }

  return @($value).Count
}

function Get-RuntimeReadinessRecordOrNull {
  param(
    [AllowNull()][object]$RuntimeReadiness,
    [string]$Key
  )

  if ($null -eq $RuntimeReadiness) {
    return $null
  }

  $records = @($RuntimeReadiness)
  foreach ($record in $records) {
    if ($record.PSObject.Properties.Name -contains "key" -and [string]$record.key -eq $Key) {
      return $record
    }
  }

  if ($records.Count -gt 0) {
    return $records[0]
  }

  return $null
}

function Test-PackageConsumerNativeAssetsReady {
  param([AllowNull()][object]$PackageConsumer)

  if ($null -eq $PackageConsumer) {
    return $false
  }

  $expected = [int](Get-PropertyOrDefault -Object $PackageConsumer -Name "NativeAssetsExpected" -DefaultValue -1)
  $found = [int](Get-PropertyOrDefault -Object $PackageConsumer -Name "NativeAssetsFound" -DefaultValue -1)
  $missingCount = Get-ArrayPropertyCountOrDefault -Object $PackageConsumer -Name "MissingNativeAssets" -DefaultValue -1

  return $expected -gt 0 -and $found -ge $expected -and $missingCount -eq 0
}

function Get-PackageConsumerStatus {
  param([AllowNull()][object]$PackageConsumer)

  if ($null -eq $PackageConsumer) {
    return "missing-package-consumer"
  }

  $validationState = [string](Get-PropertyOrDefault -Object $PackageConsumer -Name "ValidationState" -DefaultValue "missing-validation-state")
  $expected = [int](Get-PropertyOrDefault -Object $PackageConsumer -Name "NativeAssetsExpected" -DefaultValue -1)
  $found = [int](Get-PropertyOrDefault -Object $PackageConsumer -Name "NativeAssetsFound" -DefaultValue -1)
  $missingCount = Get-ArrayPropertyCountOrDefault -Object $PackageConsumer -Name "MissingNativeAssets" -DefaultValue -1
  $smokeResult = [string](Get-PropertyOrDefault -Object $PackageConsumer -Name "SmokeResult" -DefaultValue "missing-smoke-result")
  $evidenceKind = [string](Get-PropertyOrDefault -Object $PackageConsumer -Name "EvidenceKind" -DefaultValue "missing-evidence-kind")
  $isRuntimeExecutionEvidence = [bool](Get-PropertyOrDefault -Object $PackageConsumer -Name "IsRuntimeExecutionEvidence" -DefaultValue $false)
  $isDependencyProbeOnly = [bool](Get-PropertyOrDefault -Object $PackageConsumer -Name "IsDependencyProbeOnly" -DefaultValue $true)
  $nativeAssetStatus = if (Test-PackageConsumerNativeAssetsReady -PackageConsumer $PackageConsumer) {
    "native-assets-ready"
  }
  else {
    "native-assets-incomplete expected=$expected found=$found missing=$missingCount"
  }

  return "$nativeAssetStatus; validation=$validationState; smoke=$smokeResult; evidence=$evidenceKind; runtimeExecution=$isRuntimeExecutionEvidence; dependencyProbeOnly=$isDependencyProbeOnly"
}

function New-EvidenceItem {
  param(
    [string]$Id,
    [string]$Title,
    [string]$Artifact,
    [string]$State,
    [bool]$Passed,
    [string]$Boundary
  )

  [pscustomobject]@{
    id = $Id
    title = $Title
    artifact = $Artifact
    state = $State
    passed = $Passed
    boundary = $Boundary
  }
}

function ConvertTo-MarkdownCell {
  param([AllowNull()][object]$Value)

  if ($null -eq $Value) {
    return ""
  }

  return ([string]$Value).Replace("|", "\|").Replace("`r", " ").Replace("`n", " ")
}

function Test-Sha256Ready {
  param([AllowNull()][object]$Value)

  $text = [string]$Value
  return -not [string]::IsNullOrWhiteSpace($text) -and [System.Text.RegularExpressions.Regex]::IsMatch($text, "^[0-9a-fA-F]{64}$")
}

