$trt11DllResolutionOwnerActionRequired = [bool](Get-PropertyOrDefault -Object $trt11DllResolutionReport -Name "ownerActionRequired" -DefaultValue $true)
$trt11DllResolutionCanPromoteRuntimeProof = [bool](Get-PropertyOrDefault -Object $trt11DllResolutionReport -Name "canPromoteRuntimeProof" -DefaultValue $false)
$trt11DllResolutionIsRuntimeExecutionProof = [bool](Get-PropertyOrDefault -Object $trt11DllResolutionReport -Name "isRuntimeExecutionProof" -DefaultValue $false)
$trt11DllResolutionIsPackageConsumerRuntimeProof = [bool](Get-PropertyOrDefault -Object $trt11DllResolutionReport -Name "isPackageConsumerRuntimeProof" -DefaultValue $false)
$trt10VsTrt11BridgeRuntimeDiagnosticDiffState = [string](Get-PropertyOrDefault -Object $trt10VsTrt11BridgeRuntimeDiagnosticDiff -Name "reportState" -DefaultValue "missing-trt10-vs-trt11-bridge-runtime-diagnostic-diff")
$trt10VsTrt11BridgeRuntimeDiagnosticDiffDifferingFieldCount = [int](Get-PropertyOrDefault -Object $trt10VsTrt11BridgeRuntimeDiagnosticDiff -Name "differingFieldCount" -DefaultValue 0)
$trt10VsTrt11BridgeRuntimeDiagnosticDiffTrt10SmokePassed = [bool](Get-PropertyOrDefault -Object $trt10VsTrt11BridgeRuntimeDiagnosticDiff -Name "trt10SmokePassed" -DefaultValue $false)
$trt10VsTrt11BridgeRuntimeDiagnosticDiffTrt11SmokeFailed = [bool](Get-PropertyOrDefault -Object $trt10VsTrt11BridgeRuntimeDiagnosticDiff -Name "trt11SmokeFailed" -DefaultValue $false)
$trt10VsTrt11BridgeRuntimeDiagnosticDiffFailureSignature = [string](Get-PropertyOrDefault -Object $trt10VsTrt11BridgeRuntimeDiagnosticDiff -Name "trt11FailureSignature" -DefaultValue "missing-failure-signature")
$trt10VsTrt11BridgeRuntimeDiagnosticDiffCanPromoteRuntimeProof = [bool](Get-PropertyOrDefault -Object $trt10VsTrt11BridgeRuntimeDiagnosticDiff -Name "canPromoteRuntimeProof" -DefaultValue $false)
$trt10VsTrt11BridgeRuntimeDiagnosticDiffIsRuntimeExecutionProof = [bool](Get-PropertyOrDefault -Object $trt10VsTrt11BridgeRuntimeDiagnosticDiff -Name "isRuntimeExecutionProof" -DefaultValue $false)
$trt10VsTrt11BridgeRuntimeDiagnosticDiffIsPackageConsumerRuntimeProof = [bool](Get-PropertyOrDefault -Object $trt10VsTrt11BridgeRuntimeDiagnosticDiff -Name "isPackageConsumerRuntimeProof" -DefaultValue $false)
$cleanPublicPackageConsumerProofGapReportState = [string](Get-PropertyOrDefault -Object $cleanPublicPackageConsumerProofGapReport -Name "reportState" -DefaultValue "missing-clean-public-package-consumer-proof-gap-report")
$cleanPublicPackageConsumerProofGapCount = [int](Get-PropertyOrDefault -Object $cleanPublicPackageConsumerProofGapReport -Name "gapCount" -DefaultValue -1)
$cleanPublicPackageConsumerProofOwnerActionRequiredCount = [int](Get-PropertyOrDefault -Object $cleanPublicPackageConsumerProofGapReport -Name "ownerActionRequiredCount" -DefaultValue -1)
$cleanPublicPackageConsumerProofOwnerInputFailedActionRequiredCount = [int](Get-PropertyOrDefault -Object $cleanPublicPackageConsumerProofGapReport -Name "ownerInputFailedActionRequiredCount" -DefaultValue -1)
$cleanPublicPackageConsumerProofCanPromoteRuntimeProof = [bool](Get-PropertyOrDefault -Object $cleanPublicPackageConsumerProofGapReport -Name "canPromoteRuntimeProof" -DefaultValue $false)
$cleanPublicPackageConsumerProofCanPublishPublicly = [bool](Get-PropertyOrDefault -Object $cleanPublicPackageConsumerProofGapReport -Name "canPublishPublicly" -DefaultValue $false)
$cleanPublicPackageConsumerProofCanCloseReleaseIssue = [bool](Get-PropertyOrDefault -Object $cleanPublicPackageConsumerProofGapReport -Name "canCloseReleaseIssue" -DefaultValue $false)
$projectQualityShardCoverageState = [string](Get-PropertyOrDefault -Object $projectQualityShardClassCoverage -Name "coverageState" -DefaultValue "missing-project-quality-shard-class-coverage")
$projectQualityShardCoverageInventoryClassCount = [int](Get-PropertyOrDefault -Object $projectQualityShardClassCoverage -Name "inventoryClassCount" -DefaultValue 0)
$projectQualityShardCoverageCoveredClassCount = [int](Get-PropertyOrDefault -Object $projectQualityShardClassCoverage -Name "coveredClassCount" -DefaultValue 0)
$projectQualityShardCoverageMissingClassCount = [int](Get-PropertyOrDefault -Object $projectQualityShardClassCoverage -Name "missingClassCount" -DefaultValue -1)
$projectQualityShardCoverageInvalidEvidenceCount = [int](Get-PropertyOrDefault -Object $projectQualityShardClassCoverage -Name "invalidEvidenceCount" -DefaultValue -1)
$projectQualityShardCoverageStrictPassedTrxCount = [int](Get-PropertyOrDefault -Object $projectQualityShardClassCoverage -Name "strictPassedTrxCount" -DefaultValue 0)
$projectQualityShardCoverageComplete = $projectQualityShardCoverageState -eq "complete-class-coverage" -and $projectQualityShardCoverageInventoryClassCount -gt 0 -and $projectQualityShardCoverageInventoryClassCount -eq $projectQualityShardCoverageCoveredClassCount -and $projectQualityShardCoverageMissingClassCount -eq 0 -and $projectQualityShardCoverageInvalidEvidenceCount -eq 0
$projectQualityReleaseTimeoutSingleClassRunState = [string](Get-PropertyOrDefault -Object $projectQualityReleaseTimeoutSingleClassSummary -Name "runState" -DefaultValue "missing-release-timeout-single-class-shard-summary")
$projectQualityReleaseTimeoutSingleClassExecutedTests = [int](Get-PropertyOrDefault -Object $projectQualityReleaseTimeoutSingleClassSummary -Name "totalExecutedTests" -DefaultValue 0)
$projectQualityReleaseTimeoutSingleClassPassedTests = [int](Get-PropertyOrDefault -Object $projectQualityReleaseTimeoutSingleClassSummary -Name "totalPassedTests" -DefaultValue 0)
$projectQualityReleaseTimeoutSingleClassFailedTests = [int](Get-PropertyOrDefault -Object $projectQualityReleaseTimeoutSingleClassSummary -Name "totalFailedTests" -DefaultValue -1)
$projectQualityReleaseTimeoutSingleClassTimedOutShardCount = [int](Get-PropertyOrDefault -Object $projectQualityReleaseTimeoutSingleClassSummary -Name "timedOutShardCount" -DefaultValue -1)
$deferredSafetyTriageKind = [string](Get-PropertyOrDefault -Object $deferredSafetyTriage -Name "triageKind" -DefaultValue "missing-deferred-candidate-safety-triage")
$deferredSafetyTriageTotalRows = [int](Get-PropertyOrDefault -Object $deferredSafetyTriage -Name "totalTriageRowCount" -DefaultValue 0)
$deferredSafetyTierSummaries = @((Get-PropertyOrDefault -Object $deferredSafetyTriage -Name "tierSummaries" -DefaultValue @()))
$deferredSafetyTierAImmediateSafeCount = [int](Get-PropertyOrDefault -Object ($deferredSafetyTierSummaries | Where-Object { $_.safetyTier -eq "A - immediate-safe" } | Select-Object -First 1) -Name "candidateCount" -DefaultValue 0)
$deferredSafetyTierBSafeAlternativeCount = [int](Get-PropertyOrDefault -Object ($deferredSafetyTierSummaries | Where-Object { $_.safetyTier -eq "B - safe-alternative-or-alias" } | Select-Object -First 1) -Name "candidateCount" -DefaultValue 0)
$deferredSafetyTierCDesignGateCount = [int](Get-PropertyOrDefault -Object ($deferredSafetyTierSummaries | Where-Object { $_.safetyTier -eq "C - design-gate-required" } | Select-Object -First 1) -Name "candidateCount" -DefaultValue 0)
$deferredSafetyTierDKeepDeferredCount = [int](Get-PropertyOrDefault -Object ($deferredSafetyTierSummaries | Where-Object { $_.safetyTier -eq "D - keep-deferred" } | Select-Object -First 1) -Name "candidateCount" -DefaultValue 0)
$deferredSafetyTriageState = if ($deferredSafetyTriageKind -eq "deferred-candidate-safety-triage") { "triage-ready-planning-input-only" } else { "missing-deferred-safety-triage" }
$deferredSafetyTriageProofBoundary = "Deferred safety triage is release boundary disclosure only: B safe-alternative/alias rows are proof-closure planning input, C rows require design gates, D rows stay deferred, and no tier is package-consumer-runtime proof, owner approval, post-publish verification, or permission to delete deferred records."
$finalProofReadinessBlockerDashboardState = [string](Get-PropertyOrDefault -Object $finalProofReadinessBlockerDashboard -Name "dashboardState" -DefaultValue "missing-final-proof-readiness-blocker-dashboard")
$finalProofReadinessBlockerDashboardBlockerCount = [int](Get-PropertyOrDefault -Object $finalProofReadinessBlockerDashboard -Name "blockerCount" -DefaultValue 0)
$finalProofReadinessBlockerDashboardOwnerActionRequiredCount = [int](Get-PropertyOrDefault -Object $finalProofReadinessBlockerDashboard -Name "ownerActionRequiredCount" -DefaultValue 0)
$finalProofReadinessBlockerDashboardReadyForPromotionCount = [int](Get-PropertyOrDefault -Object $finalProofReadinessBlockerDashboard -Name "readyForPromotionCount" -DefaultValue 0)
$finalProofReadinessBlockerDashboardCanPromoteRuntimeProof = [bool](Get-PropertyOrDefault -Object $finalProofReadinessBlockerDashboard -Name "canPromoteRuntimeProof" -DefaultValue $false)
$finalProofReadinessBlockerDashboardCanPublishPublicly = [bool](Get-PropertyOrDefault -Object $finalProofReadinessBlockerDashboard -Name "canPublishPublicly" -DefaultValue $false)
$finalProofReadinessBlockerDashboardCanCloseReleaseIssue = [bool](Get-PropertyOrDefault -Object $finalProofReadinessBlockerDashboard -Name "canCloseReleaseIssue" -DefaultValue $false)
$finalProofReadinessBlockerDashboardIsRuntimeExecutionProof = [bool](Get-PropertyOrDefault -Object $finalProofReadinessBlockerDashboard -Name "isRuntimeExecutionProof" -DefaultValue $false)
$finalProofReadinessBlockerDashboardIsPostPublishProof = [bool](Get-PropertyOrDefault -Object $finalProofReadinessBlockerDashboard -Name "isPostPublishProof" -DefaultValue $false)

$canPublishPublicly = $ownerApprovalCanPublishPublicly -and $promotionCanPublishPublicly
$isReleaseEvidenceComplete = $canPublishPublicly -and
  $canExecutePublicPublish -and
  $canPromoteRuntimeProof -and
  $canCloseReleaseIssue -and
  $isRealLinuxRunnerProof -and
  $realCallbackRuntimeProof -and
  $staleFindingCount -eq 0

if ($isReleaseEvidenceComplete) {
  $bundleState = "release-evidence-complete"
}
else {
  $bundleState = "blocked-evidence-incomplete"
}

$evidenceItems = @(
  New-EvidenceItem -Id "owner-approval-input-validation" -Title "Owner approval input validation" -Artifact "artifacts/final-release/release-owner-approval-input-validation.json" -State $ownerApprovalStatus -Passed $ownerApprovalCanPublishPublicly -Boundary "Owner approval must be a real non-template record."
  New-EvidenceItem -Id "final-release-dry-run" -Title "Final release dry run" -Artifact "artifacts/final-release/final-release-dry-run-summary.json" -State $finalReleaseStatus -Passed ($finalReleaseBlockingIssueCount -eq 0 -and $null -ne $finalRelease) -Boundary "ready-needs-manual-approval is not public release approval."
  New-EvidenceItem -Id "package-consumer-validation" -Title "Package consumer validation" -Artifact "artifacts/package-consumer/package-consumer-validation-summary.json" -State $packageConsumerStatus -Passed $packageConsumerNativeAssetsReady -Boundary "Native asset readiness is tracked separately from runtime execution proof; DependencyProbe-only and driver-blocked output are not runtime execution proof."
  New-EvidenceItem -Id "yolovision-reference-asset-acquisition" -Title "YoloVision reference asset acquisition" -Artifact "artifacts/yolovision/reference-assets/acquisition-report.json" -State "$yoloVisionReferenceAssetAcquisitionState; filesReady=$yoloVisionReferenceAssetFilesReady; licensesReady=$yoloVisionReferenceAssetLicensesReady; licenseFailures=$yoloVisionReferenceAssetLicenseFailureCount; canPromoteRealModelRuntime=$yoloVisionReferenceAssetCanPromoteRealModelRuntime; canPublishPublicly=$yoloVisionReferenceAssetCanPublishPublicly" -Passed $false -Boundary "Reference asset length and SHA256 verification do not approve redistribution; model, labels, and image license owner review remains required before real-model-runtime or public publish promotion."
  New-EvidenceItem -Id "yolovision-reference-asset-license-approval" -Title "YoloVision reference asset license approval validation" -Artifact "artifacts/yolovision/reference-assets/asset-license-approval-validation.json" -State "$yoloVisionReferenceAssetLicenseApprovalValidationState; failedBlockers=$yoloVisionReferenceAssetLicenseApprovalFailedBlockerCount; ownerActionRequired=$yoloVisionReferenceAssetLicenseApprovalOwnerActionRequiredCount; allAssetsApproved=$yoloVisionReferenceAssetLicenseApprovalAllAssetsApproved; allHashesMatchAcquisitionReport=$yoloVisionReferenceAssetLicenseApprovalAllHashesMatchAcquisitionReport; canPromoteRealModelRuntime=$yoloVisionReferenceAssetLicenseApprovalCanPromoteRealModelRuntime; canPublishPublicly=$yoloVisionReferenceAssetLicenseApprovalCanPublishPublicly" -Passed $yoloVisionReferenceAssetLicenseApprovalAllAssetsApproved -Boundary "License approval validation is owner-action evidence only. Hash-ready local assets, acquisition success, and TensorRT SLA text cannot substitute for owner-approved model, labels, and image redistribution rights, so this cannot promote real-model-runtime, public publish, or release close while ownerActionRequired remains nonzero."
  New-EvidenceItem -Id "trt10-bridge-runtime-consumer" -Title "TRT10 bridge package runtime consumer" -Artifact "artifacts/package-consumer/bridge-runtime/win-x64-trt10.11-cuda12.9-cudnn9.22/bridge-package-runtime-consumer-proof.json" -State "$trt10BridgeRuntimeConsumerClassification; smoke=$trt10BridgeRuntimeConsumerSmokeStatus; sourceRuntimeKey=$trt10BridgeRuntimeConsumerSourceKey; runtimeExecution=$trt10BridgeRuntimeConsumerIsRuntimeExecutionProof; packageConsumerProof=$trt10BridgeRuntimeConsumerIsPackageConsumerRuntimeProof; identityOutputMatch=$trt10BridgeRuntimeConsumerIdentityOutputMatch; enqueueCompleted=$trt10BridgeRuntimeConsumerEnqueueCompleted; canPromoteRuntimeProof=$trt10BridgeRuntimeConsumerCanPromoteRuntimeProof" -Passed $trt10BridgeRuntimeConsumerSmokePassed -Boundary "Compatible-host bridge package runtime smoke is real execution for this local feed bridge line only; it is not public clean package-consumer proof and cannot clear other TensorRT/CUDA runtime lines."
  New-EvidenceItem -Id "trt11-bridge-runtime-consumer" -Title "TRT11 bridge package runtime consumer attempt" -Artifact "artifacts/package-consumer/bridge-runtime/win-x64-trt11.0-cuda13.2-cudnn9.22/bridge-package-runtime-consumer-proof.json" -State "$trt11BridgeRuntimeConsumerClassification; smoke=$trt11BridgeRuntimeConsumerSmokeStatus; exitCode=$trt11BridgeRuntimeConsumerExitCode; sourceRuntimeKey=$trt11BridgeRuntimeConsumerSourceKey; runtimeExecution=$trt11BridgeRuntimeConsumerIsRuntimeExecutionProof; packageConsumerProof=$trt11BridgeRuntimeConsumerIsPackageConsumerRuntimeProof; cudaPreflight=$trt11BridgeRuntimeConsumerCudaPreflightAvailable/$trt11BridgeRuntimeConsumerCudaPreflightAttempted/driver=$trt11BridgeRuntimeConsumerCudaPreflightDriverVersion/runtime=$trt11BridgeRuntimeConsumerCudaPreflightRuntimeVersion/devices=$trt11BridgeRuntimeConsumerCudaPreflightDeviceCount/init=$trt11BridgeRuntimeConsumerCudaPreflightInitStatus/canAttemptTensorRT=$trt11BridgeRuntimeConsumerCudaPreflightCanAttemptTensorRtRuntimeCreate; identityOutputMatch=$trt11BridgeRuntimeConsumerIdentityOutputMatch; enqueueCompleted=$trt11BridgeRuntimeConsumerEnqueueCompleted; canPromoteRuntimeProof=$trt11BridgeRuntimeConsumerCanPromoteRuntimeProof" -Passed $trt11BridgeRuntimeConsumerSmokePassed -Boundary "TRT11 bridge package restore/build reached runtime smoke on a short external consumer path and captures CUDA preflight markers, but the CUDA 13.2/TensorRT 11 smoke failed on this host. This failed compatible-host attempt is evidence, not public clean package-consumer proof, and cannot promote runtime proof."
  New-EvidenceItem -Id "trt11-runtime-smoke-root-cause-report" -Title "TRT11 runtime smoke root cause report" -Artifact "artifacts/final-release/trt11-runtime-smoke-root-cause-report.json" -State "$trt11RootCauseReportState; signature=$trt11RootCauseFailureSignature; category=$trt11RootCauseCategory; subcategory=$trt11RootCauseSubcategory; tensorRtAvailable=$trt11RootCauseTensorRtAvailable; cudaAvailable=$trt11RootCauseCudaAvailable; cudaPreflight=$trt11RootCauseCudaPreflightAvailable/$trt11RootCauseCudaPreflightAttempted/driver=$trt11RootCauseCudaPreflightDriverVersion/runtime=$trt11RootCauseCudaPreflightRuntimeVersion/devices=$trt11RootCauseCudaPreflightDeviceCount/init=$trt11RootCauseCudaPreflightInitStatus/canAttemptTensorRT=$trt11RootCauseCudaPreflightCanAttemptTensorRtRuntimeCreate; nativeCreateDiag=$trt11RootCauseNativeCreateRuntimeDiagnosticAvailable/$trt11RootCauseNativeCreateRuntimeAttempted/$trt11RootCauseNativeCreateRuntimeReturnedNull/$trt11RootCauseNativeCreateRuntimeLastStatus; phase=$trt11RootCauseNativeCreateRuntimePhase; loggerMessages=$trt11RootCauseNativeCreateRuntimeLoggerMessageCount; canPromoteRuntimeProof=$trt11RootCauseCanPromoteRuntimeProof" -Passed $false -Boundary "TRT11 root-cause report is diagnostic blocker evidence only; it does not run runtime smoke, publish packages, approve release close, or promote runtime proof while smokeStatus is not passed."
  New-EvidenceItem -Id "trt11-runtime-dll-resolution-report" -Title "TRT11 runtime DLL resolution report" -Artifact "artifacts/final-release/trt11-runtime-dll-resolution-report.json" -State "$trt11DllResolutionReportState; missingRequiredDllGroups=$trt11DllResolutionMissingRequiredDllGroupCount; duplicateDllGroups=$trt11DllResolutionDuplicateDllGroupCount; ownerActionRequired=$trt11DllResolutionOwnerActionRequired; canPromoteRuntimeProof=$trt11DllResolutionCanPromoteRuntimeProof" -Passed $false -Boundary "TRT11 DLL resolution report is diagnostic blocker evidence only; it inspects local DLL paths and artifacts and cannot substitute runtime smoke, public clean package-consumer proof, post-publish proof, release approval, or package publication."
  New-EvidenceItem -Id "trt10-vs-trt11-bridge-runtime-diagnostic-diff" -Title "TRT10 vs TRT11 bridge runtime diagnostic diff" -Artifact "artifacts/final-release/trt10-vs-trt11-bridge-runtime-diagnostic-diff.json" -State "$trt10VsTrt11BridgeRuntimeDiagnosticDiffState; differingFields=$trt10VsTrt11BridgeRuntimeDiagnosticDiffDifferingFieldCount; trt10Passed=$trt10VsTrt11BridgeRuntimeDiagnosticDiffTrt10SmokePassed; trt11Failed=$trt10VsTrt11BridgeRuntimeDiagnosticDiffTrt11SmokeFailed; signature=$trt10VsTrt11BridgeRuntimeDiagnosticDiffFailureSignature; canPromoteRuntimeProof=$trt10VsTrt11BridgeRuntimeDiagnosticDiffCanPromoteRuntimeProof" -Passed $false -Boundary "TRT10/TRT11 bridge diagnostic diff is diagnostic blocker evidence only; it compares local compatible-host bridge smoke lines and cannot substitute public clean package-consumer proof, post-publish proof, runtime proof promotion, or release approval."
  New-EvidenceItem -Id "clean-public-package-consumer-proof-gap-report" -Title "Clean public package consumer proof gap report" -Artifact "artifacts/final-release/clean-public-package-consumer-proof-gap-report.json" -State "$cleanPublicPackageConsumerProofGapReportState; gaps=$cleanPublicPackageConsumerProofGapCount; ownerActionRequired=$cleanPublicPackageConsumerProofOwnerActionRequiredCount; failedActionRequired=$cleanPublicPackageConsumerProofOwnerInputFailedActionRequiredCount; canPromoteRuntimeProof=$cleanPublicPackageConsumerProofCanPromoteRuntimeProof" -Passed $false -Boundary "Clean public package consumer proof gap report is owner-action planning evidence only; it does not publish packages, run a clean consumer, run runtime smoke, approve release close, or promote package-consumer-runtime proof."
  New-EvidenceItem -Id "project-quality-shard-class-coverage" -Title "ProjectQuality shard class coverage" -Artifact "artifacts/test-analysis/project-quality-shard-class-coverage.json" -State "$projectQualityShardCoverageState; classes=$projectQualityShardCoverageCoveredClassCount/$projectQualityShardCoverageInventoryClassCount; missing=$projectQualityShardCoverageMissingClassCount; strictPassedTrx=$projectQualityShardCoverageStrictPassedTrxCount; invalidEvidence=$projectQualityShardCoverageInvalidEvidenceCount; releaseHeavyRun=$projectQualityReleaseTimeoutSingleClassRunState" -Passed $projectQualityShardCoverageComplete -Boundary "Cumulative hash-verified class coverage is source quality evidence only; it is not a one-shot whole-suite pass, runtime proof, public publish approval, or release-close proof."
  New-EvidenceItem -Id "final-proof-readiness-blocker-dashboard" -Title "Final proof readiness blocker dashboard" -Artifact "artifacts/final-release/final-proof-readiness-blocker-dashboard.json" -State "$finalProofReadinessBlockerDashboardState; blockers=$finalProofReadinessBlockerDashboardBlockerCount; ownerActionRequired=$finalProofReadinessBlockerDashboardOwnerActionRequiredCount; readyForPromotion=$finalProofReadinessBlockerDashboardReadyForPromotionCount; canPromoteRuntimeProof=$finalProofReadinessBlockerDashboardCanPromoteRuntimeProof; canPublishPublicly=$finalProofReadinessBlockerDashboardCanPublishPublicly; canCloseReleaseIssue=$finalProofReadinessBlockerDashboardCanCloseReleaseIssue" -Passed $false -Boundary "Final proof readiness blocker dashboard is owner-action aggregation only; it does not run runtime smoke, publish packages, approve release close, or promote package-consumer-runtime/post-publish proof."
  New-EvidenceItem -Id "runtime-package-readiness" -Title "Runtime package readiness" -Artifact "artifacts/package-readiness/runtime-package-readiness-summary.json" -State $runtimeReadinessStatus -Passed (-not $runtimeProofRequiredForRelease -and $runtimeProofStatus -eq "ready") -Boundary "runtimeProofRequiredForRelease=true keeps runtime proof unresolved."
  New-EvidenceItem -Id "error-recorder-diagnostics-design-gate" -Title "ErrorRecorder diagnostics design gate" -Artifact "artifacts/package-readiness/runtime-package-readiness-summary.json" -State "$errorRecorderDiagnosticsDesignGateState; runtimeProofBlocked=$errorRecorderDiagnosticsDesignGateRuntimeBlocked; proof=$errorRecorderDiagnosticsDesignGateIsProof" -Passed $false -Boundary "Design gate evidence is pointer-free boundary documentation, not runtime execution proof or publication approval."
  New-EvidenceItem -Id "dimension-expression-snapshot-design-gate" -Title "Dimension expression snapshot design gate" -Artifact "artifacts/package-readiness/runtime-package-readiness-summary.json" -State "$dimensionExpressionSnapshotDesignGateState; runtimeProofBlocked=$dimensionExpressionSnapshotDesignGateRuntimeBlocked; proof=$dimensionExpressionSnapshotDesignGateIsProof" -Passed $false -Boundary "Design gate evidence keeps IDimensionExpr/IExprBuilder deferred and cannot promote runtime proof."
  New-EvidenceItem -Id "calibrator-metadata-design-gate" -Title "Calibrator metadata design gate" -Artifact "artifacts/package-readiness/runtime-package-readiness-summary.json" -State "$calibratorMetadataDesignGateState; runtimeProofBlocked=$calibratorMetadataDesignGateRuntimeBlocked; proof=$calibratorMetadataDesignGateIsProof" -Passed $false -Boundary "Design gate evidence allows presence/copied metadata planning only; INT8 calibrator callback, batch-buffer, and cache-buffer rows remain deferred."
  New-EvidenceItem -Id "runtime-deserialization-boundary-precheck" -Title "Runtime deserialization boundary precheck" -Artifact "artifacts/package-readiness/runtime-package-readiness-summary.json" -State "$runtimeDeserializationBoundaryPrecheckState; runtimeProofBlocked=$runtimeDeserializationBoundaryPrecheckRuntimeBlocked; proof=$runtimeDeserializationBoundaryPrecheckIsProof" -Passed $false -Boundary "Precheck evidence documents safe managed Deserialize overloads and keeps direct deserializeCudaEngineV2/loadRuntime rows deferred; it is not runtime execution proof."
  New-EvidenceItem -Id "runtime-deserialization-dependency-diagnostics" -Title "Runtime deserialization dependency diagnostics" -Artifact "artifacts/package-readiness/runtime-package-readiness-summary.json" -State "$runtimeDeserializationDependencyDiagnosticsState; classification=$runtimeDeserializationDependencyDiagnosticsPackageConsumerEvidenceClassification; blockerCategory=$runtimeDeserializationDependencyDiagnosticsRuntimeProofBlockerCategory; dependencyProbeOnly=$runtimeDeserializationDependencyDiagnosticsDependencyProbeOnly; blockedByCudaDriver=$runtimeDeserializationDependencyDiagnosticsBlockedByCudaDriver; driverMismatch=$runtimeDeserializationDependencyDiagnosticsDriverRuntimeMismatchClassified; externalRuntimeProofRequired=$runtimeDeserializationDependencyDiagnosticsExternalRuntimeProofRequired; canPromoteRuntimeProof=$runtimeDeserializationDependencyDiagnosticsCanPromoteRuntimeProof; proof=$runtimeDeserializationDependencyDiagnosticsIsProof" -Passed $false -Boundary "Dependency diagnostics distinguish dependency-probe-only and blocked-by-cuda-driver from package-consumer runtime proof; direct deserializeCudaEngineV2/loadRuntime rows remain deferred."
  New-EvidenceItem -Id "runtime-proof-blocker-owner-action" -Title "Runtime proof blocker owner action" -Artifact "artifacts/package-readiness/runtime-package-readiness-summary.json" -State "$runtimeProofBlockerOwnerActionStatus; category=$runtimeProofBlockerOwnerActionCategory; externalInputRequired=$runtimeProofBlockerOwnerActionExternalInputRequired" -Passed $false -Boundary "Owner-action guidance and command sequences do not prove runtime execution; blocked-by-cuda-driver is not smoke passed."
  New-EvidenceItem -Id "linux-runner-validation" -Title "Linux runner validation" -Artifact "artifacts/linux-dry-run/$LinuxRuntimePackageKey/linux-runner-evidence-validation.json" -State $linuxValidationState -Passed $isRealLinuxRunnerProof -Boundary "template-only and handoff-only are not Linux runner proof."
  New-EvidenceItem -Id "external-runtime-proof-validation" -Title "External runtime proof validation" -Artifact "artifacts/final-release/external-runtime-proof-validation.json" -State "$externalRuntimeProofState; classification=$externalRuntimeProofClassification; promotable=$externalRuntimeProofClassificationPromotable; runtimePackageKeyMatches=$externalRuntimeProofRuntimePackageKeyMatches; packageSourceRuntimePackageKeyMatches=$externalRuntimeProofPackageSourceRuntimePackageKeyMatches; consumerProjectIdentityReady=$externalRuntimeProofConsumerProjectIdentityReady; smokeCommandRuntimeKeyReady=$externalRuntimeProofSmokeCommandRuntimeKeyReady; hostReady=$externalRuntimeProofHostReady; commandsReady=$externalRuntimeProofCommandsReady; managedNupkgSha256Ready=$externalRuntimeProofManagedNupkgSha256Ready; runtimeNupkgSha256Ready=$externalRuntimeProofRuntimeNupkgSha256Ready; logSha256Ready=$externalRuntimeProofLogSha256FormatReady; logSha256Matches=$externalRuntimeProofLogSha256Matches; failedProofItemCount=$externalRuntimeProofFailedProofItemCount" -Passed $canPromoteRuntimeProof -Boundary "Template, example, build-only, DependencyProbe-only, precheck, synthetic-input-runtime, real-model-runtime, driver-blocked, runtime-key-mismatched, missing consumer identity, missing host metadata, missing --runtime-package-key smoke command, missing package hashes, and missing-log-hash records are not promotable package-consumer runtime proof."
  New-EvidenceItem -Id "external-runtime-proof-owner-handoff" -Title "External runtime proof owner handoff" -Artifact "artifacts/final-release/external-runtime-proof-owner-handoff.json" -State "$externalRuntimeOwnerHandoffState; ownerAction=$externalRuntimeOwnerHandoffOwnerActionStatus" -Passed $false -Boundary "Owner handoff commands and expected artifact paths help a compatible CUDA host backfill proof; the handoff is not runtime proof."
  New-EvidenceItem -Id "compatible-host-runtime-proof-runbook" -Title "Compatible host runtime proof runbook" -Artifact "artifacts/final-release/compatible-host-runtime-proof-runbook.json" -State "$compatibleHostRunbookState; ownerRuntimeSmokeRunbookState=$compatibleHostRunbookOwnerRuntimeSmokeState; compatibleHostRequired=$compatibleHostRunbookCompatibleHostRequired; canPromoteRuntimeProof=$compatibleHostRunbookCanPromoteRuntimeProof; proof=$compatibleHostRunbookRuntimeExecutionEvidence; promotionBlockedReason=$compatibleHostRunbookPromotionBlockedReason" -Passed $compatibleHostRunbookCanPromoteRuntimeProof -Boundary "The runbook gives compatible-host commands and record fields only; it does not publish packages, approve public release, or prove runtime execution."
  New-EvidenceItem -Id "compatible-host-runtime-proof-runbook-validation" -Title "Compatible host runtime proof runbook validation" -Artifact "artifacts/final-release/compatible-host-runtime-proof-runbook-validation.json" -State "$compatibleHostRunbookValidationState; failedBlockers=$compatibleHostRunbookValidationFailedBlockerCount; ownerRuntimeSmokeRunbookState=$compatibleHostRunbookOwnerRuntimeSmokeState; canPromoteRuntimeProof=$compatibleHostRunbookValidationCanPromoteRuntimeProof; canPublishPublicly=$compatibleHostRunbookValidationCanPublishPublicly; canCloseReleaseIssue=$compatibleHostRunbookValidationCanCloseReleaseIssue" -Passed $false -Boundary "Runbook validation checks the owner runtime smoke command chain and forbidden substitutes only; it is not runtime proof, publication approval, package push, or release close approval."
