$outputRoot = Join-Path $RepositoryRoot "artifacts\final-release"
New-Item -ItemType Directory -Path $outputRoot -Force | Out-Null
$jsonPath = Join-Path $outputRoot "release-evidence-bundle.json"
$markdownPath = Join-Path $outputRoot "release-evidence-bundle.md"

Write-Utf8FileWithRetry -LiteralPath $jsonPath -InputObject ($record | ConvertTo-Json -Depth 10)

$oneScreenReleaseHoldRows = $oneScreenReleaseHoldChecklist | ForEach-Object {
  $item = $_
  $id = ConvertTo-MarkdownCell (Get-PropertyOrDefault -Object $item -Name "id" -DefaultValue "")
  $blocker = ConvertTo-MarkdownCell (Get-PropertyOrDefault -Object $item -Name "ownerVisibleBlocker" -DefaultValue "")
  $currentState = ConvertTo-MarkdownCell (Get-PropertyOrDefault -Object $item -Name "currentState" -DefaultValue "")
  $nextAction = ConvertTo-MarkdownCell (Get-PropertyOrDefault -Object $item -Name "ownerNextAction" -DefaultValue "")
  $validator = ConvertTo-MarkdownCell (Get-PropertyOrDefault -Object $item -Name "validatorCommand" -DefaultValue "")
  "| ``$id`` | $blocker | $currentState | $nextAction | ``$validator`` |"
}

