$lines.Add("## One-Screen Release Hold Checklist")
$lines.Add("")
$lines.Add("This owner-facing checklist is guidance only. It keeps performsPublish=false and canCloseReleaseIssue=false while surfacing the current blockers, first owner actions, and validators.")
$lines.Add("")
$lines.Add("| ID | Owner visible blocker | Current state | Owner next action | Validator |")
$lines.Add("| --- | --- | --- | --- | --- |")
foreach ($row in $oneScreenReleaseHoldRows) {
  $lines.Add($row)
}
$lines.Add("")
$lines.Add("## Non-Substitute Proof Kinds")
$lines.Add("")
$lines.Add("The following evidence kinds are never sufficient to promote release proof, close the release issue, or publish publicly:")
$lines.Add("")
foreach ($kind in $record.nonSubstituteProofKinds) {
  $lines.Add("- ``$kind``")
}
$lines.Add("")
$lines.Add("## Post-Publish Required Evidence")
$lines.Add("")
foreach ($field in $postPublishRequiredEvidence) {
  $lines.Add("- ``$field``")
}
$lines.Add("")
$lines.Add("## Evidence Items")
$lines.Add("")
$lines.Add("| ID | State | Passed | Artifact | Boundary |")
$lines.Add("| --- | --- | --- | --- | --- |")
foreach ($item in $evidenceItems) {
  $lines.Add("| ``$($item.id)`` | ``$($item.state)`` | ``$($item.passed)`` | ``$($item.artifact)`` | $(ConvertTo-MarkdownCell $item.boundary) |")
}
$lines.Add("")
$lines.Add("## Safety Notes")
$lines.Add("")
foreach ($note in $record.safetyNotes) {
  $lines.Add("- $note")
}

Write-Utf8FileWithRetry -LiteralPath $markdownPath -InputObject $lines

Write-Host "Release evidence bundle written to $jsonPath"
Write-Host "Release evidence bundle written to $markdownPath"
